CREATE TABLE stg_orders AS SELECT o.order_id, o.order_date, o.distributor, o.amount_usd
FROM raw_orders o
JOIN load_log l ON l.batch_id = o.batch_id
WHERE o.line_no <= l.rows_loaded;
CREATE TABLE mart_daily_revenue AS SELECT order_date AS day, COUNT(*) AS orders, SUM(amount_usd) AS revenue_usd
FROM stg_orders
GROUP BY order_date;
